messages.content:
Tool response:
Tool: create_lease_deal
Description: Create Lease Deal
Parameters:
    {
      "type": "object",
      "properties": {
        "customer_id": {
          "type": "integer",
          "title": "Customer Id"
        },
        "vehicle_id": {
          "type": "integer",
          "title": "Vehicle Id"
        },
        "term_months": {
          "type": "integer",
          "title": "Term Months"
        },
        "annual_mileage": {
          "type": "integer",
          "title": "Annual Mileage"
        },
        "down_payment": {
          "type": "number",
          "title": "Down Payment"
        },
        "monthly_payment": {
          "type": "number",
          "title": "Monthly Payment"
        },
        "add_ons": {
          "anyOf": [
            {
              "items": {
                "properties": {
                  "add_on_id": {
                    "type": "integer",
                    "title": "Add On Id"
                  },
                  "price": {
                    "anyOf": [
                      {
                        "type": "number"
                      },
                      {
                        "type": "null"
                      }
                    ],
                    "title": "Price"
                  },
                  "quantity": {
                    "anyOf": [
                      {
                        "type": "integer"
                      },
                      {
                        "type": "null"
                      }
                    ],
                    "title": "Quantity",
                    "default": 1
                  }
                },
                "type": "object",
                "required": [
                  "add_on_id"
                ],
                "title": "AddOnItem"
              },
              "type": "array"
            },
            {
              "type": "null"
            }
          ],
          "title": "Add Ons"
        }
      },
      "required": [
        "customer_id",
        "vehicle_id",
        "term_months",
        "annual_mileage",
        "down_payment",
        "monthly_payment"
      ]
    }

Tool response:
Tool: get_deal_details
Description: Get Deal Details
Parameters:
    {
      "type": "object",
      "properties": {
        "deal_id": {
          "type": "integer",
          "title": "Deal Id",
          "description": ""
        }
      },
      "required": [
        "deal_id"
      ]
    }
